(function(){"use strict";var desktop=window.matchMedia("(min-width: 901px)");var original=new Map;var pending;var observer;function restore(){original.forEach(function(saved,element){if(saved.value)element.style.setProperty("font-size",saved.value,saved.priority);else element.style.removeProperty("font-size")});original.clear()}function apply(){observer.disconnect();restore();if(desktop.matches){var sizes=[];document.querySelectorAll("body *").forEach(function(element){if(element.closest("svg,script,style,iframe"))return;var hasText=Array.from(element.childNodes).some(function(node){return node.nodeType===3&&node.textContent.trim()});if(!hasText&&!element.matches("input,textarea,select"))return;var size=parseFloat(getComputedStyle(element).fontSize);if(!Number.isFinite(size))return;original.set(element,{value:element.style.getPropertyValue("font-size"),priority:element.style.getPropertyPriority("font-size")});sizes.push([element,size])});sizes.forEach(function(entry){entry[0].style.setProperty("font-size",entry[1]*.8+"px","important")})}observer.observe(document.body,{childList:true,subtree:true})}function schedule(){clearTimeout(pending);pending=setTimeout(apply,180)}function init(){observer=new MutationObserver(function(records){var newText=records.some(function(record){return Array.from(record.addedNodes).some(function(node){return node.nodeType===1&&node.textContent.trim()})});if(newText)schedule()});apply();window.addEventListener("resize",schedule);desktop.addEventListener("change",schedule);window.addEventListener("beforeprint",function(){clearTimeout(pending);observer.disconnect();restore()});window.addEventListener("afterprint",apply)}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",init);else init()})();